use std::collections::HashMap;

pub struct Counter {
    counts: HashMap<String, u32>,
}

impl Counter {
    pub fn new() -> Self {
        Counter { counts: HashMap::new() }
    }

    /// Increment the count for key by 1.
    pub fn increment(&mut self, key: &str) {
        // BUG: sets to 1 instead of incrementing
        self.counts.insert(key.to_string(), 1);
    }

    /// Return the current count for key (0 if absent).
    pub fn get(&self, key: &str) -> u32 {
        *self.counts.get(key).unwrap_or(&0)
    }

    /// Reset the count for key to 0 (remove from map).
    pub fn reset(&mut self, key: &str) {
        // BUG: inserts 0 instead of removing
        self.counts.insert(key.to_string(), 0);
    }

    /// Return up to n keys with the highest counts, sorted descending by count.
    pub fn top_n<'a>(&'a self, items: &[&'a str], n: usize) -> Vec<&'a str> {
        // BUG: returns first n items without sorting
        items.iter().take(n).copied().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_increment_multiple_times() {
        let mut c = Counter::new();
        c.increment("a");
        c.increment("a");
        c.increment("a");
        assert_eq!(c.get("a"), 3);
    }

    #[test]
    fn test_get_absent() {
        let c = Counter::new();
        assert_eq!(c.get("missing"), 0);
    }

    #[test]
    fn test_reset_removes_key() {
        let mut c = Counter::new();
        c.increment("x");
        c.increment("x");
        c.reset("x");
        assert_eq!(c.get("x"), 0);
        // After reset, key should not show up in top_n
        let items = ["x"];
        let top = c.top_n(&items, 1);
        assert!(top.is_empty(), "expected empty top_n after reset");
    }

    #[test]
    fn test_top_n_sorted() {
        let mut c = Counter::new();
        c.increment("a");
        c.increment("b");
        c.increment("b");
        c.increment("c");
        c.increment("c");
        c.increment("c");
        let items = ["a", "b", "c"];
        let top = c.top_n(&items, 2);
        assert_eq!(top, vec!["c", "b"]);
    }
}
